/* APLUS P6 English Prelim — Generation Engine V6.2 */
(function(){
'use strict';
const KEY='APLUS_P6_PRELIM_SESSION_V2',DONE='APLUS_P6_PRELIM_COMPLETED_V2',TOTAL=6600;
const BP=[
{id:'grammar',name:'BOOKLET A · Grammar',count:10,marks:10,b:'A',kind:'mcq'},
{id:'vocabulary',name:'BOOKLET A · Vocabulary',count:5,marks:5,b:'A',kind:'mcq'},
{id:'vocabularyCloze',name:'BOOKLET A · Vocabulary Cloze',count:5,marks:5,b:'A',kind:'mcq'},
{id:'visual',name:'BOOKLET A · Visual Text',count:5,marks:5,b:'A',kind:'mcq'},
{id:'grammarCloze',name:'BOOKLET B · Grammar Cloze',count:10,marks:10,b:'B',kind:'oe'},
{id:'editing',name:'BOOKLET B · Editing for Spelling and Grammar',count:10,marks:10,b:'B',kind:'oe'},
{id:'comprehensionCloze',name:'BOOKLET B · Comprehension Cloze',count:15,marks:15,b:'B',kind:'oe'},
{id:'synthesis',name:'BOOKLET B · Synthesis and Transformation',count:5,marks:10,b:'B',kind:'oe'},
{id:'comprehension',name:'BOOKLET B · Comprehension',count:10,marks:20,b:'B',kind:'oe'}];
let state={started:false,submitted:false,index:0,remaining:TOTAL,questions:[],answers:{},candidate:'',className:'',profile:'standard',paperId:'',seed:0},timer=null;
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function db(n){let a=window[n];if(Array.isArray(a))return a;try{a=eval(n);return Array.isArray(a)?a:[]}catch(e){return[]}}
function rng(seed){let x=seed>>>0||1;return()=>{x^=x<<13;x^=x>>>17;x^=x<<5;return(x>>>0)/4294967296}}
function sh(a,r){a=a.slice();for(let i=a.length-1;i;i--){let j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function norm(s){return String(s??'').toLowerCase().replace(/[“”‘’".,!?;:()]/g,' ').replace(/\s+/g,' ').trim()}
function uniq(a){let m=new Map();a.forEach(x=>x&&x.id&&m.set(x.id,x));return [...m.values()]}
function src(){return{
g:uniq([].concat(db('APLUS_AI_DB_V1_GRAMMAR_P6_QUESTION_BANK'),db('APLUS_AI_DB_V1_GRAMMAR_P6_EXPANSION_BATCH02'),db('APLUS_AI_DB_V1_GRAMMAR_P6_EXPANSION_BATCH03'),db('APLUS_AI_DB_V1_GRAMMAR_P6_EXPANSION_BATCH04'),db('APLUS_AI_DB_V1_P6_PSLE_PAPER2_CORE_GRAMMAR_BATCH01'))),
v:uniq([].concat(db('APLUS_AI_DB_V1_P6_PSLE_PAPER2_MASTER_VOCABULARY_CONTENT_B03'),db('APLUS_AI_DB_V1_P6_PSLE_PAPER2_CORE_VOCABULARY_BATCH02'))),
ce:uniq([].concat(db('APLUS_AI_DB_V1_P6_CLOZE_EDITING_QUESTION_BANK'),db('APLUS_AI_DB_V1_P6_CLOZE_EDITING_EXPANSION_BATCH02'),db('APLUS_AI_DB_V1_P6_CLOZE_EDITING_EXPANSION_BATCH03'),db('APLUS_AI_DB_V1_P6_CLOZE_EDITING_EXPANSION_BATCH04'))),
st:uniq([].concat(db('APLUS_AI_DB_V1_P6_SYNTHESIS_TRANSFORMATION_QUESTION_BANK'),db('APLUS_AI_DB_V1_P6_SYNTHESIS_TRANSFORMATION_EXPANSION_BATCH02'),db('APLUS_AI_DB_V1_P6_SYNTHESIS_TRANSFORMATION_EXPANSION_BATCH04'))),
comp:uniq([].concat(db('APLUS_AI_DB_V1_P6_COMPREHENSION_QUESTION_BANK'),db('APLUS_AI_DB_V1_P6_COMPREHENSION_EXPANSION_BATCH02'))),
pass:uniq([].concat(db('APLUS_AI_DB_V1_P6_COMPREHENSION_PASSAGE_SETS_BATCH01'),db('APLUS_AI_DB_V1_P6_COMPREHENSION_PASSAGE_SETS_BATCH02'))),
ed:uniq([].concat(db('APLUS_AI_DB_V1_P6_PSLE_PAPER2_MASTER_EDITING_DNA_B03'),db('APLUS_AI_DB_V1_P6_PSLE_PAPER2_CORE_EDITING_DNA_BATCH02'))),vis:uniq(db('APLUS_AI_DB_V1_P6_PSLE_PAPER2_CORE_VISUAL_TEXT_DNA_BATCH01'))}}
function band(p){return({hard:[3,5],vocabularyIntensive:[2,5],grammarIntensive:[2,5],comprehensionIntensive:[2,5],psleSimulation:[2,4],standard:[1,5],studentWeakness:[1,5]})[p]||[1,5]}
function weak(){try{let s=JSON.parse(localStorage.getItem('APLUS_AI_TUTOR_STUDENT_V7')||'{}'),a=s.accuracyBySkill||s.skillAccuracy||{};return Object.keys(a).filter(k=>Number(a[k])<.75).map(k=>k.toLowerCase())}catch(e){return[]}}
function take(a,n,r,used,strict=true){let p=a.filter(x=>x&&(!used||!used.has(x.id))),[lo,hi]=band(state.profile);let f=p.filter(x=>{let d=Number(x.difficulty);if(!Number.isFinite(d))d=3;return !strict||d>=lo&&d<=hi});if(f.length>=n)p=f;else if(p.length)p=p;return sh(p,r).slice(0,n)}
function tag(q,d,id){q.sourceDatabase=d;q.sourceRecordId=id;q.generationSeed=state.seed;return q}
function grammar(S,n,r,used){let out=[],p=take(S.g,n*6,r,used);for(let x of p){if(out.length>=n||!x.question||!Array.isArray(x.options)||!x.answer)continue;let a=x.options.filter(o=>norm(o)!==norm(x.answer));if(a.length<3)continue;let opts=sh([x.answer,...a.slice(0,3)],r);if(new Set(opts.map(norm)).size<4)continue;out.push(tag({type:'mcq',marks:1,question:x.question,options:opts,answer:x.answer,explanation:x.explanation||'',skill:x.skill||x.topic||'grammar',difficulty:Number(x.difficulty)||3},'P6 Grammar Database',x.id))}return out}
function vocab(S,n,r,used){let out=[],p=take(S.v,n*8,r,used);for(let x of p){if(out.length>=n||!x.word)continue;let clue=x.contextClue||(Array.isArray(x.contextClues)?x.contextClues.join(', '):'The situation gives a clear clue about the meaning.');let d=[...(x.antonyms||[]),...(x.synonyms||[]),...sh(S.v,r).map(y=>y.word).filter(Boolean)];d=[...new Set(d.filter(y=>norm(y)!==norm(x.word)))];if(d.length<3)continue;out.push(tag({type:'mcq',marks:1,question:'Read the sentence carefully. '+clue+' Which word best completes the sentence?',options:sh([x.word,...d.slice(0,3)],r),answer:x.word,explanation:x.definition||'',skill:'contextual word choice',difficulty:Number(x.difficulty)||3},'P6 Master Vocabulary',x.id))}return out}
function vcloze(S,n,r,used){let out=[],p=take(S.v,n*8,r,used);for(let x of p){if(out.length>=n||!x.word)continue;let clue=x.contextClue||(Array.isArray(x.contextClues)?x.contextClues.join(', '):'The context provides enough information.');let d=sh(S.v.filter(y=>y.word&&y.word!==x.word),r).slice(0,3).map(y=>y.word);if(d.length<3)continue;out.push(tag({type:'mcq',marks:1,question:'Read the context. '+clue+' Choose the word that best fits the context: ___',options:sh([x.word,...d],r),answer:x.word,explanation:x.definition||'',skill:'vocabulary cloze',difficulty:Number(x.difficulty)||3},'P6 Vocabulary Cloze Database',x.id))}return out}
const VT=[{title:'SCHOOL READING WEEK',rows:[['Monday','Book Swap','3.00–4.00 p.m.','Library','Bring up to three books.'],['Tuesday','Author Talk','2.30–3.30 p.m.','Hall','Sign up by Friday.'],['Wednesday','Storytelling','1.30–2.30 p.m.','Library','Open to P4–P6.'],['Thursday','Bookmark Design','3.00–4.00 p.m.','Art Room','Submit designs by Wednesday.'],['Friday','Reading Challenge','2.00–3.00 p.m.','Hall','Complete a 20-minute reading task.']]},{title:'GREEN CAMPUS DAY',rows:[['Monday','Planting Session','3.00–4.00 p.m.','Garden','Wear covered shoes.'],['Tuesday','Recycling Drive','2.00–3.00 p.m.','Block A','Bring clean recyclables.'],['Wednesday','Water-Saving Talk','1.30–2.15 p.m.','Hall','Open to all pupils.'],['Thursday','Poster Display','2.30–4.00 p.m.','Library','Vote for one poster.'],['Friday','Clean-Up Walk','3.00–4.00 p.m.','Main Gate','Bring gloves.']]}];
function visual(S,n,r){let t=VT[Math.floor(r()*VT.length)],rows=t.rows,txt='Day | Activity | Time | Venue | Important Information\n'+rows.map(x=>x.join(' | ')).join('\n'),q=[['When is '+rows[1][1]+' held?',[rows[1][2],rows[0][2],rows[2][2],rows[4][2]],rows[1][2]],['Where is '+rows[2][1]+' held?',[rows[2][3],rows[1][3],rows[3][3],rows[0][3]],rows[2][3]],['What instruction applies to '+rows[0][1]+'?',[rows[0][4],rows[1][4],rows[2][4],rows[4][4]],rows[0][4]],['Which activity takes place in the '+rows[3][3]+'?',[rows[3][1],rows[0][1],rows[1][1],rows[4][1]],rows[3][1]],['Which statement is supported by the visual text?',[rows[3][1]+' requires designs by Wednesday.',rows[4][1]+' is held in the Library.',rows[1][1]+' is open only to P4–P6.',rows[0][1]+' is held in the Hall.'],rows[3][1]+' requires designs by Wednesday.']];return q.slice(0,n).map((x,i)=>tag({type:'mcq',marks:1,visual:{title:t.title,text:txt},question:x[0],options:sh(x[1],r),answer:x[2],explanation:'The answer is directly supported by the visual text.',skill:'visual text',difficulty:2},'P6 Visual Text Database','VIS-'+t.title+'-'+i))}
function cloze(S,n,r,used){let p=take(S.ce.filter(x=>x.type==='cloze'&&x.answer),n*3,r,used),out=[];for(let x of p){if(out.length>=n||!x.text)continue;let t=String(x.text);if(!/___|__+|\[blank\]/.test(t)){let re=new RegExp(String(x.answer).replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));t=t.replace(re,'___')}out.push(tag({type:'oe',marks:1,passage:t,question:'Fill in the blank with the most suitable word.',answer:String(x.answer),acceptedPatterns:[String(x.answer)],explanation:x.explanation||'',skill:x.skill||'cloze',difficulty:Number(x.difficulty)||3},'P6 Cloze Database',x.id))}return out}
function editing(S,n,r,used){let pool=S.ed.filter(x=>x.original&&x.corrected&&norm(x.original)!==norm(x.corrected)),out=[];for(let x of take(pool,n*2,r,used))out.push(tag({type:'oe',marks:1,passage:x.original,question:'Correct the error in the sentence. Write the corrected sentence.',answer:x.corrected,acceptedPatterns:[x.corrected],explanation:x.rule||x.explanation||'',skill:x.errorType||x.skill||'editing',difficulty:Number(x.difficulty)||3},'P6 Editing DNA',x.id));if(out.length<n)for(let x of take(S.ce.filter(x=>x.type==='editing'&&x.answer),n*3,r,used,false)){if(out.length>=n)break;out.push(tag({type:'oe',marks:1,passage:x.text,question:'Correct the sentence.',answer:x.answer,acceptedPatterns:[x.answer],explanation:x.explanation||'',skill:x.skill||'editing',difficulty:Number(x.difficulty)||3},'P6 Editing Database',x.id))}return out}
function synth(S,n,r,used){return take(S.st.filter(x=>x.answer),n*5,r,used,false).slice(0,n).map(x=>tag({type:'oe',marks:2,question:x.question,answer:x.answer,acceptedPatterns:x.acceptedPatterns||[x.answer],explanation:x.explanation||'',skill:x.skill||'synthesis',difficulty:Number(x.difficulty)||3},'P6 Synthesis and Transformation Database',x.id))}
function comp(S,n,r,used){let out=[];for(let p of sh(S.pass,r)){let qs=Array.isArray(p.questions)?sh(p.questions,r):[];for(let q of qs){if(out.length>=n)break;let a=q.answer;if(typeof a==='number'&&Array.isArray(q.options))a=q.options[a];if(!q.question||a==null)continue;let id=(p.passageId||p.id)+'::'+(q.id||q.question);out.push(tag({type:'oe',marks:2,passage:p.text||p.passage||'',question:q.question,answer:String(a),acceptedPatterns:[String(a)],explanation:q.explanation||'',skill:q.skill||q.type||'comprehension',difficulty:Number(q.difficulty)||3},'P6 Comprehension Passage Sets',id))}}if(out.length<n)for(let q of take(S.comp.filter(x=>x.question&&x.answer!=null&&x.passage),n-out.length,r,used,false)){if(out.length>=n)break;out.push(tag({type:'oe',marks:2,passage:q.passage,question:q.question,answer:String(q.answer),acceptedPatterns:[String(q.answer)],explanation:q.explanation||'',skill:q.skill||q.type||'comprehension',difficulty:Number(q.difficulty)||3},'P6 Comprehension Question Bank',q.id))}return out.slice(0,n)}
function build(){let S=src(),r=rng(state.seed),used=new Set(),all=[];const add=(sid,a)=>{let need=BP.find(x=>x.id===sid).count;while(a.length<need){let more=null;if(sid==='grammar')more=grammar(S,need,r,new Set());else if(sid==='vocabulary')more=vocab(S,need,r,new Set());else if(sid==='vocabularyCloze')more=vcloze(S,need,r,new Set());else if(sid==='visual')more=visual(S,need,r);else if(sid==='grammarCloze')more=cloze(S,need,r,new Set());else if(sid==='editing')more=editing(S,need,r,new Set());else if(sid==='comprehensionCloze')more=cloze(S,need,r,new Set());else if(sid==='synthesis')more=synth(S,need,r,new Set());else more=comp(S,need,r,new Set());if(!more||!more.length)break;for(let q of more){let key=q.sourceRecordId+'#'+a.length;if(a.some(z=>z.sourceRecordId===q.sourceRecordId)&&a.length<need)q=Object.assign({},q,{sourceRecordId:key});a.push(q);if(a.length>=need)break}}a.slice(0,need).forEach(q=>{let b=BP.find(x=>x.id===sid);q.number=all.length+1;q.id='Q'+q.number;q.section=sid;q.sectionName=b.name;q.booklet=b.b;q.marks=b.marks===10&&sid==='synthesis'?2:b.marks===20&&sid==='comprehension'?2:b.marks===15?1:b.marks===10?1:1;all.push(q);used.add(q.sourceRecordId)})};
add('grammar',grammar(S,10,r,used));add('vocabulary',vocab(S,5,r,used));add('vocabularyCloze',vcloze(S,5,r,used));add('visual',visual(S,5,r));add('grammarCloze',cloze(S,10,r,used));add('editing',editing(S,10,r,used));add('comprehensionCloze',cloze(S,15,r,used));add('synthesis',synth(S,5,r,used));add('comprehension',comp(S,10,r,used));return all}
function validate(q){let marks=q.reduce((s,x)=>s+x.marks,0);return q.length===75&&marks===90&&BP.every(b=>q.filter(x=>x.section===b.id).length===b.count)&&q.every(x=>x.type==='oe'?x.answer&&x.sourceRecordId:x.options&&x.options.length===4&&x.options.includes(x.answer)&&new Set(x.options.map(norm)).size===4)}
function generate(){for(let i=0;i<20;i++){state.seed=(Date.now()+Math.floor(Math.random()*0xffffffff)+i*7919)>>>0;let q=build();if(validate(q))return q}return[]}
function show(id){document.querySelectorAll('.screen').forEach(x=>x.classList.remove('active'));$(id).classList.add('active')}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){}}
function time(x){x=Math.max(0,Math.floor(x));return String(Math.floor(x/3600)).padStart(2,'0')+':'+String(Math.floor(x%3600/60)).padStart(2,'0')+':'+String(x%60).padStart(2,'0')}
function nav(){let box=$('sectionNav');box.innerHTML='';BP.forEach(b=>{let h=document.createElement('div');h.className='nav-section';h.innerHTML='<div class="nav-section-title">'+esc(b.name)+'</div>';state.questions.forEach((q,i)=>{if(q.section===b.id){let x=document.createElement('button');x.className='nav-q '+(state.answers[q.number]?'answered ':'')+(i===state.index?'current':'');x.textContent=q.number;x.onclick=()=>{state.index=i;save();render()};h.appendChild(x)}});box.appendChild(h)})}
function render(){let q=state.questions[state.index];if(!q)return;let b=BP.find(x=>x.id===q.section);$('bookletLabel').textContent='BOOKLET '+q.booklet;$('sectionLabel').textContent=b.name.replace('BOOKLET A · ','').replace('BOOKLET B · ','');$('progressText').textContent='Question '+q.number+' of 75';$('progressBar').style.width=(q.number/75*100)+'%';$('markText').textContent=q.marks+' '+(q.marks===1?'mark':'marks');let h='<div class="q-kicker">'+esc(q.sectionName)+'</div><h2>Question '+q.number+'</h2>';if(q.visual)h+='<div class="visual"><strong>'+esc(q.visual.title)+'</strong><pre>'+esc(q.visual.text)+'</pre></div>';if(q.passage)h+='<div class="passage">'+esc(q.passage)+'</div>';h+='<div class="question-text">'+esc(q.question)+'</div>';if(q.type==='mcq')h+='<div class="options">'+q.options.map((o,i)=>'<label class="option"><input type="radio" name="q" value="'+esc(o)+'" '+(norm(state.answers[q.number])===norm(o)?'checked':'')+'><span class="letter">'+String.fromCharCode(65+i)+'.</span><span>'+esc(o)+'</span></label>').join('')+'</div>';else h+='<textarea id="oeAnswer" placeholder="Type your answer here">'+esc(state.answers[q.number]||'')+'</textarea>';$('questionCard').innerHTML=h;document.querySelectorAll('input[name=q]').forEach(x=>x.onchange=()=>{state.answers[q.number]=x.value;save();nav()});let ta=$('oeAnswer');if(ta){ta.oninput=()=>{state.answers[q.number]=ta.value;save()}}$('prevBtn').disabled=state.index===0;$('nextBtn').textContent=state.index===74?'FINISH':'Next';nav()}
function tick(){if(!state.started||state.submitted)return;if(--state.remaining<=0){state.remaining=0;save();submit(true)}$('timer').textContent=time(state.remaining);if(state.remaining%5===0)save()}
function grade(q,a){let n=norm(a);if(!n)return 0;let acc=(q.acceptedPatterns||[q.answer]).map(norm);if(acc.includes(n))return q.marks;if(q.type==='oe'&&q.marks===2){let k=norm(q.answer).split(' ').filter(x=>x.length>3),hits=k.filter(x=>n.includes(x)).length;if(k.length&&hits>=Math.ceil(k.length*.75))return 2;if(k.length&&hits>=Math.ceil(k.length*.35))return 1}return 0}
function result(auto){let score=0;state.questions.forEach(q=>{q.awarded=grade(q,state.answers[q.number]);score+=q.awarded});state.score=score;state.percentage=Math.round(score/90*100);state.submitted=true;state.submittedAt=new Date().toISOString();clearInterval(timer);try{localStorage.setItem(DONE,JSON.stringify(state));localStorage.removeItem(KEY)}catch(e){}$('paperId').textContent=state.paperId+' · '+state.candidate;$('score').textContent=score+' / 90';$('percentage').textContent=state.percentage+'%';$('resultMessage').textContent=auto?'Time is up. The paper has been submitted automatically.':state.percentage>=80?'Strong progress.':state.percentage>=50?'More practice is needed in selected areas.':'Let’s rebuild the basics step by step.';let sh='<h3>Section Results</h3>';BP.forEach(b=>{let a=state.questions.filter(q=>q.section===b.id),s=a.reduce((v,q)=>v+(q.awarded||0),0);sh+='<div class="result-row"><span>'+esc(b.name)+'</span><strong>'+s+' / '+b.marks+'</strong></div>'});$('sectionResults').innerHTML=sh;show('result')}
function submit(auto){result(auto)}
function start(){state.profile=$('paperProfile').value||'standard';state.questions=generate();if(state.questions.length!==75){alert('Paper generation is temporarily unavailable. Please refresh and try again.');return}state.started=true;state.submitted=false;state.index=0;state.remaining=TOTAL;state.answers={};state.candidate=($('candidateName').value||'').trim();state.className=($('candidateClass').value||'').trim();state.paperId='APLUS-P6-ENG-P2-'+new Date().getFullYear()+'-'+String(state.seed).padStart(10,'0');save();show('exam');$('timer').textContent=time(TOTAL);clearInterval(timer);timer=setInterval(tick,1000);render()}
function bind(){if(localStorage.getItem(KEY)){try{let x=JSON.parse(localStorage.getItem(KEY));if(x&&x.questions&&x.questions.length===75){state=x;$('resumeBtn').classList.remove('hidden');$('resumeBtn').onclick=()=>{show('exam');clearInterval(timer);timer=setInterval(tick,1000);render()}}}catch(e){}}$('startBtn').onclick=start;$('prevBtn').onclick=()=>{if(state.index){state.index--;save();render()}};$('nextBtn').onclick=()=>{if(state.index<74){state.index++;save();render()}else{let n=Object.values(state.answers).filter(x=>String(x).trim()).length;$('submitSummary').innerHTML='<p><strong>'+n+' / 75</strong> questions answered.</p>';show('submitScreen')}};$('confirmSubmitBtn').onclick=()=>submit(false);$('backToExamBtn').onclick=()=>{show('exam');render()};$('reviewBtn').onclick=()=>{show('exam');state.index=0;render()};$('printBtn').onclick=()=>window.print();$('newExamBtn').onclick=()=>{localStorage.removeItem(DONE);state={started:false,submitted:false,index:0,remaining:TOTAL,questions:[],answers:{},candidate:'',className:'',profile:'standard',paperId:'',seed:0};show('landing')}}
window.APLUS_P6_PRELIM_V62={BLUEPRINT:BP,sources:src,generate,getState:()=>state};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bind);else bind();
})();